import './App.css';
import Register from './components/Auth/Register';
import Login from './components/Auth/Login';
import Logout from './components/Auth/Logout';
import ProtectedRoute from './components/Auth/ProtectedRoute';
import CreateLog from './components/Log';
import { About, AboutPage } from './components/About';
import Footer from './components/Footer';
import NavBar from './components/NavBar';
import PrivacyPolicy from './components/PrivacyPolicy';
import TermsOfService from './components/TermsOfService';
import CookieBanner from './components/CookieBanner';
import HowToUse from './components/HowToUse';
import AccountSettings from './components/AccountSettings';
import api, { setApiToken } from './api';
import { useState, useEffect} from 'react';
import { useAuth } from './components/Auth/AuthProvider';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import NotFound from './components/NotFound';
import ServerError from './components/ServerError';
import usePushNotifications from './hooks/usePushNotifications';
import ErrorBoundary from './components/ErrorBoundary';



function App() {
  const { token, setToken, isAuthenticated } = useAuth();
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [updateAvailable, setUpdateAvailable] = useState(false);
  const [waitingWorker, setWaitingWorker] = useState(null);
  usePushNotifications(isAuthenticated);

  useEffect(() => {
    const goOffline = () => setIsOffline(true);
    const goOnline = () => setIsOffline(false);
    window.addEventListener('offline', goOffline);
    window.addEventListener('online', goOnline);
    return () => {
      window.removeEventListener('offline', goOffline);
      window.removeEventListener('online', goOnline);
    };
  }, []);

  useEffect(() => {
    const handler = (event) => {
      setWaitingWorker(event.detail);
      setUpdateAvailable(true);
    };
    window.addEventListener('swUpdateAvailable', handler);
    return () => window.removeEventListener('swUpdateAvailable', handler);
  }, []);

  // whenever the token changes, call the setApiToken (declared in api.js)
  useEffect(() => {
    setApiToken(token);
  }, [token]);

  // only response interceptor here now (the request is moved n api.js, check the explanation there)

  useEffect(() => {
    // Response interceptor
    //  api.interceptors.response.use() takes two arguments (two functions), separatedby comma, success function and error function.
    const responseInterceptor = api.interceptors.response.use(
      // If successful, return response
      (response) => response, 
      
      //  If error
      async (error) => {
        if (error.config?.url?.includes('/accounts/google/')) {
          return Promise.reject(error);
        }
        if (error.config?.url?.includes('/accounts/logout/')) {
          return Promise.reject(error);
        }
        if (error.config?.url?.includes('/token/') && !error.config?.url?.includes('refresh')) {
          return Promise.reject(error);
        }
        if (error.config?.url?.includes('/token/refresh/')) {
          if (error.config?._isInitialRefresh) {
              return Promise.reject(error);
          }
          setToken(null);
          window.location.href = '/login';
          return Promise.reject(error);
        }

        const originalRequest = error.config;

        // Check if it is a 401 error(means the token expired)
        if (error.response?.status === 401 && !originalRequest._retry) {

          originalRequest._retry = true;  // Prevent infinite loop
          
          try {
            // Get a new token, and set the new value of the access token
            const newToken = await api.post('/token/refresh/');
            setToken(newToken.data.access);
            setApiToken(newToken.data.access);  
            // Add the token to the authorization header
            originalRequest.headers.Authorization = `Bearer ${newToken.data.access}`;
            // Retry to send the request with the new value
            return api(originalRequest); 
          }catch (refreshError) {
            // Refresh failed - redirect to login
            setToken(null);
            window.location.href = '/login'; // Force redirect
            return Promise.reject(refreshError);
          }
        }
        return Promise.reject(error);
      }
    );

    // Clean 
    return () => {
      api.interceptors.response.eject(responseInterceptor);
    };
  }, [setToken]);

  return (
    <Router>
      <NavBar/>
      {isOffline && (
        <div className="offline-banner">
          Your past memories are safely stored, but you need an internet connection to reach them. Please check your network.
        </div>
      )}
      {updateAvailable && (
        <div className="update-banner">
          <div className="update-banner-inner">
            A new version is available!{' '}
            <button onClick={() => {
              waitingWorker?.postMessage({ type: 'SKIP_WAITING' });
              setUpdateAvailable(false);
            }}>
              Update now
            </button>
          </div>
        </div>
      )}
      <Routes>
        <Route path='/' element={<AboutPage/>} />
        <Route path='/about' element={<About/>} /> 
        <Route path='/logout' element={<Logout/>} />
        <Route path='/register' element={<Register/>} />
        <Route path='/login' element={<Login/>} />
        {/* next Route will be wrapped in ProtectedRoute */}
        <Route path="/createlog" element={ <ProtectedRoute> <ErrorBoundary> <CreateLog /> </ErrorBoundary> </ProtectedRoute> } />
        {/* <Route path="/question" element={ <ProtectedRoute> <Question /> </ProtectedRoute> } /> */}
        <Route path="/account" element={<ProtectedRoute><AccountSettings /></ProtectedRoute>} />
        <Route path='/privacy-policy' element={<PrivacyPolicy />} />
        <Route path='/terms-of-service' element={<TermsOfService />} />
        <Route path='/how-to-use' element={<HowToUse />} />
        <Route path="/500" element={<ServerError />} />
        <Route path="*" element={<NotFound />} /> 
      </Routes>
      <Footer />
      <CookieBanner />
    </Router>
  );
}
export default App;

