import { Alert, Button, Container, Form } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faArrowUp, faMicrophone, faStop } from '@fortawesome/free-solid-svg-icons';
import { useEffect, useState, useRef } from 'react';
import usePushNotifications from '../hooks/usePushNotifications';
import { Link } from 'react-router-dom';
import api from '../api';
import { ShowLogs } from './ShowLogs';
import { useVoiceRecording } from './useVoiceRecording';
import {useAuth} from './Auth/AuthProvider';
import Question from './Question';
import './Log.css';
import ErrorBoundary from './ErrorBoundary';

const NOTIF_PROMPT_UNSUB_KEY = 'heydayta_notif_prompt_unsub_last_shown';
const NOTIF_PROMPT_DENIED_KEY = 'heydayta_notif_prompt_denied_seen';
const NOTIF_PROMPT_COOLDOWN_MS = 7 * 24 * 60 * 60 * 1000; // 7 days


// CreateLog
function CreateLog() {
    // Get the correct date and time (for the reminders)
    const localDate = new Date().getTimezoneOffset(); 

    const [entryType, setEntryType] = useState('journal');
    const [entry, setEntry] = useState('');
    const [error, setError] = useState(null);
    const [success, setSuccess] = useState(null);
    const [logs, setLogs] = useState([]);

    const [filter, setFilter] = useState('all');
    const textareaRef = useRef(null);
    const scrollTimerRef = useRef(null);

    const [isLoadingLogs, setIsLoadingLogs] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [clearQuestion, setClearQuestion] = useState(0);
    const [reminderTime, setReminderTime] = useState(null);
    const [showScrollTop, setShowScrollTop] = useState(false);
    const [showNotifPrompt, setShowNotifPrompt] = useState(false);
    const [reminderJustCreated, setReminderJustCreated] = useState(false);


    useEffect(() => {
        const handleScroll = () => {
            if (scrollTimerRef.current) clearTimeout(scrollTimerRef.current);
            if (window.scrollY <= 350) {
                setShowScrollTop(false);
                return;
            }
            setShowScrollTop(false);
            scrollTimerRef.current = setTimeout(() => {
                setShowScrollTop(window.scrollY > 350);
            }, 200);
        };
        window.addEventListener('scroll', handleScroll);
        return () => {
            window.removeEventListener('scroll', handleScroll);
            if (scrollTimerRef.current) clearTimeout(scrollTimerRef.current);
        };
    }, []);

    const { isAuthenticated } = useAuth();
    const { notifStatus, isNotifLoading, notifError, enableNotifications } = usePushNotifications(isAuthenticated);

    // Auto-expand textarea function
    const handleTextareaChange = (e) => {
        setEntry(e.target.value);
        setError(null);
        // Auto-expand textarea
        const textarea = e.target;
        textarea.style.height = 'auto';
        textarea.style.height = textarea.scrollHeight + 'px';
        const maxH = parseInt(getComputedStyle(textarea).maxHeight);
        textarea.style.overflowY = textarea.scrollHeight > maxH ? 'auto' : 'hidden';
    };


    function fetchLogs() {
        setIsLoadingLogs(true);
        api.get('/logs/')
        .then((response) => {
            setLogs(response.data);
        })
        .catch((error) => {
            if (!navigator.onLine || !error.response) {
                // Network error - app is offline, fail silently, banner handles UX
                setLogs([]);
            } else {
                console.error('Failed to fetch logs:', error);
            }
        })
        .finally(() => {
            setIsLoadingLogs(false);
        });
    }

    const filteredLogs = logs.filter(
        log => filter === 'all' ? true : log.entry_type === filter
    );


    const { isRecording, startRecording, stopRecording } = useVoiceRecording(
        (transcribedText) => {
            setEntry(prev => {
                const newEntry = prev + (prev ? ' ' : '') + transcribedText;
                // Trigger auto-expand after voice input
                setTimeout(() => {
                    if (textareaRef.current) {
                        const el = textareaRef.current;
                        el.style.height = 'auto';
                        el.style.height = el.scrollHeight + 'px';
                        const maxH = parseInt(getComputedStyle(el).maxHeight);
                        el.style.overflowY = el.scrollHeight > maxH ? 'auto' : 'hidden';
                    }
                }, 0);
                return newEntry;
            });
            setError(null);  
        },
        (errorMessage) => {
            setError(errorMessage);
        }
    );


    useEffect(() => {
        if (!isAuthenticated) return;  // ← Don't fetch if not authenticated
        fetchLogs();
    }, [isAuthenticated]); 
    
    useEffect(() => {
        textareaRef.current?.focus();
    }, []);

    useEffect(() => {
        if (error) {
            const timer = setTimeout(() => setError(null), 6000);
            return () => clearTimeout(timer);
        }
    }, [error]);

    // Decides whether to show the notification prompt once notifStatus is
    // actually known — fixes the race where notifStatus was still 'loading'
    // at the moment the reminder save resolved.
    useEffect(() => {
        if (!reminderJustCreated) return;
        if (notifStatus === 'loading') return; // wait for it to resolve

        if (notifStatus === 'unsubscribed') {
            const lastShown = localStorage.getItem(NOTIF_PROMPT_UNSUB_KEY);
            const now = Date.now();
            if (!lastShown || (now - parseInt(lastShown, 10)) >= NOTIF_PROMPT_COOLDOWN_MS) {
                localStorage.setItem(NOTIF_PROMPT_UNSUB_KEY, String(now));
                setShowNotifPrompt(true);
            }
            setReminderJustCreated(false);
        } else if (notifStatus === 'denied') {
            if (localStorage.getItem(NOTIF_PROMPT_DENIED_KEY) !== 'true') {
                localStorage.setItem(NOTIF_PROMPT_DENIED_KEY, 'true');
                setShowNotifPrompt(true);
            }
            setReminderJustCreated(false);
        } else {
            // subscribed or unsupported — nothing to do
            setReminderJustCreated(false);
        }
    }, [reminderJustCreated, notifStatus]);

    const handleSubmit = (e) => {
        e.preventDefault();
        setIsSubmitting(true);
        const logData = {
            entry_type:entryType,
            entry: entry,
            localDate: localDate,
        }
        api.post('/logs/', logData)
        .then((response) => {
            setError(null);
            setEntry('');
            if (textareaRef.current) {
                textareaRef.current.style.height = 'auto';
            }
            fetchLogs();

            if (response.data.entry_type === 'reminders' && response.data.reminder_time) {
                try {
                    const dt = new Date(response.data.reminder_time);
                    if (!isNaN(dt.getTime())) {
                        const formatted = dt.toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
                            + ' at '
                            + dt.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
                        setReminderTime(formatted);
                    } else {
                        setReminderTime('your reminder');
                    }
                } catch(e) {
                    setReminderTime('your reminder');
                }
                setReminderJustCreated(true);
                setSuccess(null);
            } else {
                setReminderTime(null);
                setSuccess('Entry saved');
                setTimeout(() => setSuccess(null), 3000);
            }
        })
        .catch((error) => {
            if (error.response?.data?.error) {
                setError(error.response.data.error);
            } else {
                setError('Could not save entry. Please try again.');
            }
        })
        .finally(() => {
            setIsSubmitting(false);
        })
    }



    return (
        <Container className='create-log-container'>
            <Container className='create-log-form-container'>
                <Form onSubmit={handleSubmit} className='create-log-form'>
                    <div>
                        {success && <Alert variant="success">{success}</Alert>}
                        {reminderTime && (
                            <Alert variant="success" onClose={() => setReminderTime(null)} dismissible>
                                Reminder set for {reminderTime}
                            </Alert>
                        )}
                        {showNotifPrompt && notifStatus === 'unsubscribed' && (
                            <Alert variant="info" className='notif-prompt-alert' onClose={() => setShowNotifPrompt(false)} dismissible>
                                Want to also receive a push notification when this reminder is due? 
                                <Button
                                    type="button"
                                    className='notif-prompt-btn'
                                    onClick={async () => {
                                        const success = await enableNotifications();
                                        if (success) {
                                            setShowNotifPrompt(false);
                                        }
                                    }}
                                    disabled={isNotifLoading}
                                >
                                    {isNotifLoading
                                        ? <><span className="spinner-border spinner-border-sm me-2" role="status" />Enabling...</>
                                        : 'Enable Notifications'
                                    }
                                </Button>
                                {notifError && <div className='notif-prompt-error'>{notifError}</div>}
                            </Alert>
                        )}
                        {showNotifPrompt && notifStatus === 'denied' && (
                            <Alert variant="info" className='notif-prompt-alert' onClose={() => setShowNotifPrompt(false)} dismissible>
                                Push notifications are blocked for HeyDayta. To turn them on, go to Settings → Apps → HeyDayta → Notifications.
                            </Alert>
                        )}
                        {error && <Alert variant='danger' dismissible onClose={() => setError(null)}>{error}</Alert>}
                    </div>

                    {/* Top row: Just tabs */}
                    <div className='form-controls-row'>
                        <div className='entry-type-toggle'>
                            <Button
                                type="button"
                                className={`type-toggle-btn ${entryType === 'journal' ? 'type-toggle-active' : ''}`}
                                onClick={() => { setEntryType('journal'); setClearQuestion(c => c + 1); }}
                            >
                                Entry
                            </Button>
                            <Button
                                type="button"
                                className={`type-toggle-btn ${entryType === 'reminders' ? 'type-toggle-active' : ''}`}
                                onClick={() => { setEntryType('reminders'); setClearQuestion(c => c + 1); }}
                            >
                                Reminder
                            </Button>
                        </div>
                    </div>

                    {/* Textarea with mic button inside */}
                    <div className='textarea-wrapper'>
                        <Form.Control
                            ref={textareaRef}
                            id='captainsLog'
                            as="textarea"
                            rows={2}
                            placeholder={entryType === 'journal' ? "What do you want to remember?" : "Set reminder for..."}
                            aria-label="Entry text"
                            value={entry}
                            onChange={handleTextareaChange}
                            onFocus={() => setClearQuestion(c => c + 1)}
                            className='create-log-form-control bg-grey-inner'
                        />
                        
                        {/* Mic icon positioned inside textarea */}
                        <Button
                            type="button"
                            className={isRecording ? "voice-recording-btn" : "voice-mic-btn"}
                            onClick={isRecording ? stopRecording : () => { setError(null); startRecording(); }}
                        >
                            <FontAwesomeIcon icon={isRecording ? faStop : faMicrophone} />
                        </Button>
                    </div>

                    {/* Save button - right aligned */}
                    <div className='save-button-container'>
                        {entryType === 'reminders' && (
                            <Link to='/how-to-use' className='howto-hint-link' target='_blank'>
                                ❓ How to write a reminder
                            </Link>
                        )}
                        <Button type="submit" className='create-log-form-button' disabled={isSubmitting}>
                            {isSubmitting ? (
                                <>
                                    <span className="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>
                                    {entryType === 'reminders' ? 'Scheduling...' : 'Saving...'}
                                </>
                            ) : 'Log it'}
                        </Button>
                    </div>
                </Form>
            </Container>
            <Question clearSignal={clearQuestion}/>

            
            <Container className='show-logs'>
                <div className='logs-filter-row d-flex gap-2 mb-3'>
                    {/* If the button is active, add logs-buttons-active class */}
                    {/* On click, filter the logs depending on type */}
                    <Button 
                        className={`logs-buttons ${filter==='all'? 'logs-buttons-active':''}`} 
                        onClick={() => setFilter('all')}
                    >
                        All
                    </Button>
                    <Button 
                        className={`logs-buttons ${filter==='journal'? 'logs-buttons-active':''}`} 
                        onClick={() => setFilter('journal')}
                    >
                        Entry
                    </Button>
                    <Button 
                        className={`logs-buttons ${filter==='reminders'? 'logs-buttons-active':''}`} 
                        onClick={() => setFilter('reminders')}
                    >
                        Reminders
                    </Button>
                </div>
                
                {isLoadingLogs ? (
                    <div className="d-flex justify-content-center py-4">
                        <span className="spinner-border" role="status">
                            <span className="visually-hidden">Loading logs...</span>
                        </span>
                    </div>
                ) : (
                    <>
                    {logs.length === 0 ? (
                        <div className='empty-state'>
                            <h2 className='empty-state-title'>Here's how it works</h2>
                            <p className='empty-state-subline'>Write something. Ask something. Set a reminder.</p>

                            <div className='empty-state-cards'>
                                <div className='empty-state-card'>
                                    <div className='empty-state-card-label'>Brain dump your day</div>
                                    <div className='empty-state-card-example'>"Tried that new sushi place downtown. The spicy tuna was incredible."</div>
                                    <div className='empty-state-card-payoff'>Later, just ask "Where did I get sushi?" and Dayta will find it for you.</div>
                                </div>

                                <div className='empty-state-card'>
                                    <div className='empty-state-card-label'>Ask instead of search</div>
                                    <div className='empty-state-card-example'>"What was the name of that book Mark recommended?"</div>
                                    <div className='empty-state-card-payoff'>Dayta connects the dots in your entries and simply tells you the answer.</div>
                                </div>

                                <div className='empty-state-card'>
                                    <div className='empty-state-card-label'>Boss your future self around</div>
                                    <div className='empty-state-card-example'>"Remind me in two weeks to cancel my free trial."</div>
                                    <div className='empty-state-card-payoff'>No date pickers, no calendars. Just say when, and Dayta will handle the rest.</div>
                                </div>
                            </div>

                            <Link to='/how-to-use' className='empty-state-link'>Not sure where to start? See how it works →</Link>
                        </div>
                    ) : filteredLogs.length === 0 ? (
                        <div className='empty-logs-message'>
                            <p className='empty-logs-title'>
                                {filter === 'reminders' ? 'No reminders yet' : 'No entries yet'}
                            </p>
                        </div>
                    ) : null}
                        <ErrorBoundary>
                            <ShowLogs logs={filteredLogs} refreshLogs={fetchLogs}/>
                        </ErrorBoundary>
                    </>
                )}
                
                
            </Container>
            {showScrollTop && (
                <button
                    className='scroll-to-top-btn'
                    onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
                    aria-label='Scroll to top'
                >
                    <FontAwesomeIcon icon={faArrowUp} />
                </button>
            )}
        </Container>
    )
}

export default CreateLog