import { Container, Button, Form} from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import {faPenToSquare, faTrashCan, faFloppyDisk, faMicrophone, faStop, faChevronDown, faChevronUp} from '@fortawesome/free-solid-svg-icons';
import { useState, useRef, useEffect } from 'react';
import api from '../api';
import { useVoiceRecording } from './useVoiceRecording';
import './ShowLogs.css';

function formatLogDate(createdAt) {
  const d = new Date(createdAt);
  if (Number.isNaN(d.getTime())) {
    return { date: 'Unknown date', time: '' };
  }
  return {
    date: d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }),
    time: d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' }),
  };
}

export const ShowLogs = ({logs, refreshLogs}) => {

    return (
        <Container className='show-logs-container'>
            <ul className='list'>
                {logs.map((log) => 
                    (<LogCard log ={log} key={log.id} refreshLogs={refreshLogs}/>)
                )}
            </ul>
        </Container>
    )
}

export const LogCard = ({log, refreshLogs}) => {

    // state for edit
    const [editing, setEditing] = useState(false);
    const [newLog, setNewLog] = useState(log.entry);
    const [editError, setEditError] = useState(null);
    const [entryType, setEntryType] = useState(log.entry_type);
    const [expanded, setExpanded] = useState(false);
    const [isOverflowing, setIsOverflowing] = useState(false);
    const entryTextRef = useRef(null);

    useEffect(() => {
        const el = entryTextRef.current;
        if (!el) return;
        setIsOverflowing(el.scrollHeight > el.clientHeight);
    }, [newLog, editing]);

    const localDate = new Date().getTimezoneOffset();

    const { isRecording, startRecording, stopRecording } = useVoiceRecording(
        (transcribedText) => {
            setNewLog(prev => prev + (prev ? ' ' : '') + transcribedText);
            setEditError(null);
        },
        (errorMessage) => {
            setEditError(errorMessage);
        }
    );

    // Call for edit button
    function updateLog() {
        api.patch(`/logs/${log.id}/`, {entry: newLog, entry_type: entryType, localDate: localDate})
        .then((response) => {
            setNewLog(response.data.entry);
            setEditing(false);
            refreshLogs();
        })
        .catch((error) => {
            setEditError(error.response?.data?.error || 'Update failed. Please try again.');
        })
    }

    // Call for delete button
    function deleteLog() {
        api.delete(`/logs/${log.id}/`)
        .then((response) => {
            refreshLogs();
        })
    }

    const { date, time } = formatLogDate(log.created_at);
    const logClass = entryType === 'journal' ? 'log-card-journal' : 'log-card-reminder';
    const tag = entryType === 'journal' ? 'Entry' : 'Reminder';

    return (
        
        <Container className={`log-card-container ${logClass}`}>
            <div className='date-buttons-container'>
                <div className='log-meta'>
                    <span className="tag">{tag}</span>
                    <span className='log-meta-dot'>·</span>
                    <span className='date'>{date} {time}</span>
                </div>
                <div className='button-container'>
                    {editing ? 
                    (<Button className='edit-button' onClick={updateLog}>
                        <FontAwesomeIcon icon={faFloppyDisk} />
                    </Button>) :                     
                    (<Button className='edit-button' onClick={() => setEditing(true)}>
                        <FontAwesomeIcon icon={faPenToSquare} />
                    </Button>)}

                    <Button
                        className='edit-button delete'
                        onClick={deleteLog}
                    >
                        <FontAwesomeIcon icon={faTrashCan} />
                    </Button>
                </div>
            </div>
            
            {editing ? (
                <>
                    {editError && <div className='edit-error'>{editError}</div>}
                    <div className='edit-type-toggle'>
                        <button
                            type="button"
                            className={`edit-type-btn ${entryType === 'journal' ? 'edit-type-active' : ''}`}
                            onClick={() => setEntryType('journal')}
                        >
                            Journal
                        </button>
                        <button
                            type="button"
                            className={`edit-type-btn ${entryType === 'reminders' ? 'edit-type-active' : ''}`}
                            onClick={() => setEntryType('reminders')}
                        >
                            Reminder
                        </button>
                    </div>
                    <div className='textarea-wrapper'>
                        <Form.Control
                            id='editLog'
                            as="textarea"
                            placeholder={log.entry}
                            value={newLog}
                            onChange={(e) => setNewLog(e.target.value)}
                            className='create-log-form-control bg-grey-inner'
                        />
                        <Button
                            type="button"
                            className={isRecording ? "voice-recording-btn" : "voice-mic-btn"}
                            onClick={isRecording ? stopRecording : startRecording}
                        >
                            <FontAwesomeIcon icon={isRecording ? faStop : faMicrophone} />
                        </Button>
                    </div>
                </>
            ) : (
                    <div>
                        <div
                            ref={entryTextRef}
                            className={`entry-text ${expanded ? '' : 'entry-text-clamped'}`}
                        >
                            {newLog}
                        </div>
                        {isOverflowing || expanded ? (
                            <button
                                className='read-more-btn'
                                onClick={() => setExpanded(prev => !prev)}
                            >
                                <FontAwesomeIcon icon={expanded ? faChevronUp : faChevronDown} />
                                {expanded ? ' Show less' : ' Read more'}
                            </button>
                        ) : null}
                    </div>
                )}
            
        </Container>
    )
}



